pre-actions.script:
// if user not logged in save current path and params then redirect to Login
if (!ec.user.userId) { ec.web.saveScreenLastInfo(null, null); sri.sendRedirectAndStopRender('/Login'); return }

// if logged in and visiting /qapps or / directly, redirect to ZetaERP Dashboard
String reqPath = ec.web.request.requestURI
if (reqPath == '/qapps' || reqPath == '/qapps/' || reqPath == '/') { sri.sendRedirectAndStopRender('/qapps/zenith/Dashboard'); return }

// The Zenith child screen arrives after the Quasar shell. Load its styles and boot guard
// in this first response so neither the stock header nor unstyled module content paints.
// Keep these URLs in sync with ZenithApp.xml when an asset version changes.
if (reqPath == '/qapps/zenith' || reqPath.startsWith('/qapps/zenith/')) {
    if (html_stylesheets == null) html_stylesheets = []
    html_stylesheets.add('/zenithstatic/css/zenith-theme-v4.css?v=282')
    html_stylesheets.add('/zenithstatic/css/sidebar-manager.css?v=3')
    html_stylesheets.add('/zenithstatic/css/my-subscription-reference.css?v=1')
    html_stylesheets.add('/zenithstatic/css/saas-admin.css?v=4')
    html_stylesheets.add('/zenithstatic/css/product-catalog.css?v=1')
    html_stylesheets.add('/zenithstatic/css/receiving-stock.css?v=14')
    html_stylesheets.add('/zenithstatic/css/gate-passes.css?v=12')
    html_stylesheets.add('/zenithstatic/css/shops-reference.css?v=2')
    html_stylesheets.add('/zenithstatic/css/purchase-operations.css?v=2')
    html_stylesheets.add('/zenithstatic/css/contacts-dashboard.css?v=1')
    html_stylesheets.add('/zenithstatic/css/edit-customer-group.css?v=1')
    html_stylesheets.add('/zenithstatic/css/contacts-reference.css?v=1')
    html_stylesheets.add('/zenithstatic/css/sales-dashboard-reference.css?v=1')
    html_stylesheets.add('/zenithstatic/css/pricing-price-lists.css?v=1')
    html_stylesheets.add('/zenithstatic/css/purchase-rfq.css?v=2')
    html_stylesheets.add('/zenithstatic/css/purchase-job-work.css?v=2')
    html_stylesheets.add('/zenithstatic/css/purchase-vendor-bills.css?v=1')
    html_stylesheets.add('/zenithstatic/css/pos-reference.css?v=4')
    html_stylesheets.add('/zenithstatic/css/main-dashboard.css?v=12')
    html_stylesheets.add('/zenithstatic/css/pricing-history.css?v=1')
    html_stylesheets.add('/zenithstatic/css/stock-transfers.css?v=1')
    html_stylesheets.add('/zenithstatic/css/stock-levels.css?v=2')
    html_stylesheets.add('/zenithstatic/css/expiry-risk.css?v=3')
    html_stylesheets.add('/zenithstatic/css/stock-adjustments.css?v=7')
    html_stylesheets.add('/zenithstatic/css/catalogues.css?v=5')
    html_stylesheets.add('/zenithstatic/css/purchase-vendor-evaluation.css?v=1')
    html_stylesheets.add('/zenithstatic/css/pricing-rules.css?v=1')
    html_stylesheets.add('/zenithstatic/css/purchase-gstr2b.css?v=1')
    html_stylesheets.add('/zenithstatic/css/serial-tracking.css?v=5')
    html_stylesheets.add('/zenithstatic/css/demand-forecast.css?v=5')
    html_stylesheets.add('/zenithstatic/css/pricing-dashboard.css?v=2')
    html_stylesheets.add('/zenithstatic/css/pricing-reference.css?v=1')
    html_stylesheets.add('/zenithstatic/css/sales-forecast.css?v=5')
    html_stylesheets.add('/zenithstatic/css/inventory-responsive.css?v=2')
    html_stylesheets.add('https://fonts.googleapis.com/icon?family=Material+Icons')
    html_stylesheets.add('/zenithstatic/css/barcode-module.css?v=1')
    html_stylesheets.add('/zenithstatic/css/barcode-reference.css?v=1')
    html_scripts.add('/zenithstatic/js/qapps-shell-boot.js?v=1')
}

html_scripts.add('/libs/moment.js/moment-with-locales.min.js')
html_scripts.add('/libs/jquery/jquery.min.js')

String instancePurpose = System.getProperty("instance_purpose")
if (!instancePurpose || instancePurpose == 'production') {
    /* ========== Production Mode ========== */
    html_scripts.add('/js/MoquiLib.min.js')
    // Vue JS
    footer_scripts.add('/libs/vue/vue.min.js')
    // http-vue-loader
    footer_scripts.add('/js/http-vue-loader/httpVueLoader.js')
    // Quasar
    footer_scripts.add("/libs/quasar/quasar.umd.min.js")
    // Webroot Quasar-Vue instance, in footer so runs after page loaded
    footer_scripts.add('/js/WebrootVue.qvt.min.js')
} else {
    /* ========== Dev Mode ========== */
    html_scripts.add('/js/MoquiLib.js')
    // Vue JS
    footer_scripts.add('/libs/vue/vue.js')
    // http-vue-loader
    footer_scripts.add('/js/http-vue-loader/httpVueLoader.js')
    // Quasar
    footer_scripts.add("/libs/quasar/quasar.umd.min.js")
    // Webroot Quasar-Vue instance, in footer so runs after page loaded
    footer_scripts.add('/js/WebrootVue.qvt.js')
}

// Offline mode manager
footer_scripts.add('/zenithstatic/js/offline-manager.js?v=3')
footer_scripts.add('/zenithstatic/js/bfcache-guard.js?v=1')

// ZE-TAX-010: generic error handling — wraps moqui.handleAjaxError so raw 500 backend
// exceptions show a friendly message instead of internal details (loads after WebrootVue)
footer_scripts.add('/zenithstatic/js/error-handler.js')

// conditional QZ Tray scripts, only include if enabled
if (ec.user.getPreference("qz.print.enabled") == "true") {
    footer_scripts.add('/js/qz-tray/sha-256.min.js')
    footer_scripts.add('/js/qz-tray/qz-tray.min.js')
    footer_scripts.add('/js/qz-tray/MoquiQzComponent.js')
}
